package io.aegis
import android.accessibilityservice.AccessibilityService
import android.view.accessibility.*
import android.graphics.Rect
import java.util.concurrent.atomic.AtomicReference
class InspectService:AccessibilityService(){companion object{val latest=AtomicReference<Pair<String,AccessibilityNodeInfo>?>()};override fun onAccessibilityEvent(e:AccessibilityEvent?){val r=rootInActiveWindow?:return;latest.getAndSet((r.packageName?.toString()?:return) to AccessibilityNodeInfo.obtain(r))?.second?.recycle()};override fun onInterrupt(){};override fun onDestroy(){latest.getAndSet(null)?.second?.recycle()}}
object Inspector{fun scan(expected:String?=null):Pair<String,List<Candidate>>{val(pkg,root)=InspectService.latest.get()?:error("Accessibility unavailable");require(expected==null||pkg==expected);val out=mutableListOf<Candidate>();walk(root,emptyList(),out);return pkg to Mapper.map(out)};private fun walk(n:AccessibilityNodeInfo,path:List<Int>,o:MutableList<Candidate>){val b=Rect();n.getBoundsInScreen(b);if(b.width()>0&&b.height()>0&&(n.isClickable||n.isEditable||!n.text.isNullOrBlank()||!n.contentDescription.isNullOrBlank()))o+=Candidate(path,CType.UNKNOWN,listOfNotNull(n.text,n.contentDescription).joinToString(" ").take(160),n.viewIdResourceName,Box(b.left,b.top,b.right,b.bottom),n.isClickable,n.isEditable,0.0);for(i in 0 until n.childCount)n.getChild(i)?.let{walk(it,path+i,o);it.recycle()}};fun resolve(root:AccessibilityNodeInfo,c:Candidate):AccessibilityNodeInfo?{var n:AccessibilityNodeInfo?=root;for(i in c.path)n=n?.getChild(i)?:return null;return n}}
class AndroidAdapter(private val pkg:String,private val profile:()->Profile?){fun inspect()=Inspector.scan(pkg);fun act(key:String,text:String?=null):Boolean{val p=profile()?:return false;if(!p.validated)return false;val snapshot=InspectService.latest.get()?:return false;if(snapshot.first!=pkg)return false;if(Mapper.fingerprint(inspect().second)!=p.fingerprint)return false;val c=p.controls[key]?:return false;val n=Inspector.resolve(snapshot.second,c)?:return false;if(!n.isEnabled)return false;return if(text==null)n.performAction(AccessibilityNodeInfo.ACTION_CLICK)else android.os.Bundle().let{it.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,text);n.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,it)}}}
